var o=[{title:`Comece pelo objetivo`,text:`Cada movimento tem uma função: um agachamento treina em conjunto a extensão da anca e do joelho, uma remada treina a puxada e uma dobra de anca trabalha sobretudo através das ancas. A boa técnica pode parecer um pouco diferente de pessoa para pessoa porque o comprimento dos membros, a mobilidade e o equipamento variam. O que importa é um controlo seguro e repetível. Ninguém tem de corresponder a um aspeto exato.`},{title:`Construa a base`,text:`Aprenda primeiro uma versão sem carga ou com carga leve. Use uma amplitude de movimento que consiga controlar, repetições fluidas e apoio estável quando precisar. Depois progrida em pequenos passos: mais repetições, mais resistência ou uma versão mais complexa. Filmar-se ou trabalhar com um treinador qualificado pode revelar hábitos, mas o vídeo, por si só, não consegue diagnosticar uma lesão.`},{title:`Quando a técnica se desfaz`,text:`Os sinais de alerta dentro de uma série incluem perder o equilíbrio, baixar o peso sem controlo, desviar-se do trajeto pretendido ou compensações que pioram à medida que se cansa. Pare ou torne o exercício mais fácil quando os vir. Levantar mais pesado com a técnica a ruir não é progresso.`},{title:`Exemplo`,text:`Antes de carregar um levantamento romeno com halteres, pratique a dobra de anca com as mãos nas ancas e depois com um peso leve. Acrescente peso apenas quando as ancas recuarem com controlo e a posição das costas se mantiver igual de repetição para repetição para o seu corpo.`},{title:`Usar o TrainUp`,text:`O seu plano escolhe exercícios que se adaptam ao seu nível e à sua coordenação, e cada página de exercício em Exercícios tem passos e notas de técnica. O TrainUp não prescreve pesos, por isso escolhe a carga. Registe as repetições durante o treino e avalie o esforço depois e acrescente carga em pequenos passos sem perseguir um recorde em todas as sessões.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Orientações práticas do ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};